function Header() { return <header>DevDesk</header>; }
function Sidebar() { return <aside>Filtry</aside>; }
function Main() { return <main>Zgłoszenia</main>; }
export default function App() { return <div className="app-shell"><Header /><Sidebar /><Main /></div>; }

import { Header } from "./components/Header";
import { Sidebar } from "./components/Sidebar";
import { Main } from "./components/Main";

