export default function App() { return <h1>DevDesk</h1>; }

// src/main.tsx — import w innym pliku
import App from "./App";

function Header() { return <header className="app-header">DevDesk</header>; }
function Sidebar() { return <aside className="app-sidebar">Filtry</aside>; }
function Main() { return <main className="app-main">Zgłoszenia</main>; }
export default function App() { return <div className="app-shell"><Header /><Sidebar /><Main /></div>; }

